public class InnerDataAutomationProjectVideoOverrideConfigurationFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.VideoOverrideConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.VideoOverrideConfiguration>
{

    internal InnerDataAutomationProjectSensitiveDataConfigurationFactory SensitiveDataConfigurationFactory { get; set; }

    internal InnerDataAutomationProjectModalityProcessingConfigurationFactory ModalityProcessingFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.VideoOverrideConfiguration Create()
    {
        var videoOverrideConfigurationResult = CreateVideoOverrideConfiguration();
        factoryAction?.Invoke(videoOverrideConfigurationResult);

        return videoOverrideConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.VideoOverrideConfiguration CreateVideoOverrideConfiguration()
    {
        var videoOverrideConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.VideoOverrideConfiguration();

        return videoOverrideConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.VideoOverrideConfiguration result)
    {
        base.CreateChildren(result);

        result.SensitiveDataConfiguration ??= SensitiveDataConfigurationFactory?.Build();
        result.ModalityProcessing ??= ModalityProcessingFactory?.Build();
    }

} // End Of Class

